import re
import six


class BscAlarmsCollector(object):
    """
    Class to get list of alarms with all information about alarm properties
    number, fault, text, source, program_block, activity, time, date
    from output from MML BSC command ZEOL:XX; or ZEOH::BCF=XX;  (XX-bcf number)
    """

    def __init__(self, alarms_bsc_data, bsc_name):
        self.alarms_bsc_data = alarms_bsc_data
        self.bsc_name = bsc_name
        self.alarms = self._get_alarms_info()

    def __len__(self):
        return len(self.alarms)

    def __iter__(self):
        return iter(self.alarms)

    def _get_alarms_info(self):
        alarms = self._get_list_of_alarms()
        patterns_to_replace = (
            r'<HIST>',
            r'\s{}s*'.format(self.bsc_name),
            r'\sN(?!\w)',
            r'END OF BTS ALARM',
            r'(?<!\w)FF(?!\w)',
            r'(\s\d{2})(?!\d+|:)',
            r'\d{5}d',
            r'\sRP(?!\D)',
            r'\sRF\s[a-z:\s]*S',
            r'\sTRX object\s[a-zA-Z\s]*module',
            r'Local MMI connected',
        )

        for pattern in patterns_to_replace:
            alarms = [re.sub(pattern, '', alarm) for alarm in alarms]
        alarms = [re.sub(r'\s{2,}', ' ', alarm) for alarm in alarms]
        alarms = [re.sub(r'\n', ' ', alarm) for alarm in alarms]
        alarms = [alarm.rstrip() for alarm in alarms]
        return alarms

    def _get_list_of_alarms(self):  # noqa: C901
        patterns = (
            r'(?s)({}.*?)(\n\s*\n)'.format(self.bsc_name),
            r'(?s)(\s+{}.*?\r\n\r\n)'.format(self.bsc_name),
            r'(?s)\s+{}.*?\n*?'.format(self.bsc_name),
            r'(?s)<HIST>.*?\r\n\r\n',
            r'(?s)<HIST>.*?\n{2}',
        )

        self.alarms_bsc_data = six.text_type(self.alarms_bsc_data)
        alarms = []
        for pattern in patterns:
            alarms = re.findall(pattern, self.alarms_bsc_data)
            if alarms:
                break
            elif not alarms and pattern == patterns[-1]:
                try:
                    self._check_generated_output()
                except ValueError:
                    raise
                else:
                    raise RuntimeError("It is impossible to analyze alarms. Generated output did not match any of "
                                       "defined patterns. Please raise TAT ticket.")
        if all(isinstance(alarm, tuple) for alarm in alarms):
            alarms = [alarm[0] for alarm in alarms]

        return alarms

    def _check_generated_output(self):
        alarms_markers = ['EOL', 'EOH', 'BTS ALARM LISTING', 'BTS ALARM HISTORY LISTING']
        if not any(True if marker in self.alarms_bsc_data else False for marker in alarms_markers):
            raise ValueError("No alarms markers found in generated output. Please check if it was"
                             "generated properly with ZEOL or ZEOH command")


class BscAlarmsAttributesContainer(object):
    """Class to get all alarm attributes: number, fault, text, source, program_block, activity, time, date"""

    def __init__(self, alarm):
        self.alarm = alarm

    def __str__(self):
        representation = 'Alarm number: {}, fault: {}, text: {}, source {}, program block: {}, ' \
                         'activity: {}, time: {}'.format(self.number, self.fault, self.text, self.source,
                                                         self.program_block, self.activity, self.time)
        return representation

    @property
    def number(self):
        number = re.search(r'\((\d+)', self.alarm)
        return number.group(1)

    @property
    def fault(self):
        fault = re.search(r'\)\s(\d+)', self.alarm)
        return fault.group(1)

    @property
    def text(self):
        alarm_text = re.search(r'\s\d{4}\s([A-Z:&/\-\s]*)', self.alarm, re.IGNORECASE)
        return alarm_text.group(1).rstrip()

    @property
    def source(self):
        patterns = [r'(BCF-\d+)', r'(BTS-\d+)', r'(TRX-\d+)']
        sources = []
        for pattern in patterns:
            source = re.search(pattern, self.alarm)
            if source:
                sources.append(source.group(0))
        return sources

    @property
    def program_block(self):
        alarm_type = re.search(r'(?<=\d{2}\s)[a-z]*(?=\s\d+)', self.alarm, re.IGNORECASE)
        return alarm_type.group(0)

    @property
    def activity(self):
        activity = re.search(r'(\*|\.)*(ALARM|CANCEL)', self.alarm)
        if not activity:
            return ''
        return activity.group(2)

    @property
    def time(self):
        time = re.search(r'(\d+:){2}\d+\.\d+', self.alarm)
        return time.group(0)

    @property
    def date(self):
        date = re.search(r'(\d+-){2}\d+', self.alarm)
        return date.group(0)

    @property
    def alarm_data(self):
        return self.number, self.fault, self.text, self.source, \
            self.program_block, self.activity, self.time, self.date

    @property
    def alarm_data_dict(self):
        alarm_attributes_names = ['number', 'fault', 'text', 'source', 'program_block', 'activity', 'time',
                                  'date']
        return dict(zip(alarm_attributes_names, self.alarm_data))
